E=[]
def e(date,sort,title,desc,src,disputed=None,landmarks=()):
    E.append(dict(date=date,sort_year=sort,title=title,description=desc,sources=src,disputed=disputed,landmarks=list(landmarks)))
e("c. 1st half 7th c. BC",-675,"Phrygian cult centre","Phrygians build a temple/cult place of the Mother Goddess (Cybele) at the site; earliest layout of the Ploutonion with a stepped altar above the cave (Phase Ia).",[W,J32],"Date 'probably first half of 7th c. BC' is approximate.",["ploutonion"])
e("Iron Age",-800,"Iron Age settlement","Round huts of an Iron Age settlement found in 2016 in the Northern Necropolis area.",[W],None,["north_necropolis"])
e("3rd-2nd c. BC",-200,"Foundation of Hierapolis","Greek city founded. Sources disagree: Seleucid foundation (Antiochus I or Antiochus III), or Attalid foundation by Eumenes II of Pergamon after 188 BC; UNESCO says the Attalid kings founded the spa at the end of the 2nd c. BC.",[W,U,TAN,PLW],"Founder disputed: Seleucids (Antiochus I 281-261 BC / Antiochus III) vs Attalids (Eumenes II, c.190 BC). The museum displays an imago clipeata of Eumenes II captioned as founder.",[])
e("188 BC",-188,"Treaty of Apamea","After the defeat of Antiochus III at Magnesia (190 BC) the region passes to Pergamon under Eumenes II.",[W,TAN])
e("2nd c. BC",-150,"Coinage and textiles","City mints bronze coins (name 'Hieropolis'); famed for wool and dyeing using the spring water.",[W,U])
e("133 BC",-133,"Bequest to Rome","Attalus III bequeaths Pergamon to Rome; Hierapolis becomes part of the Roman province of Asia (formally organised 129 BC).",[W,U],"Province formally organised c. 129 BC after Aristonicus' revolt; '133 BC' is the bequest year.")
e("AD 17",17,"Earthquake under Tiberius","A major earthquake damages/destroys the city.",[W,TAN],"Commonly repeated; the AD 17 earthquake is attested for 12 cities of Asia (Tacitus Ann. 2.47) but Hierapolis is not named there - treat as uncertain.")
e("AD 60",60,"Earthquake under Nero","Severe earthquake ruins the city; rebuilt in Roman style with imperial support; Ploutonion monumentalised (Phase IIb).",[W,U,J32],"Tacitus (Ann. 14.27) names Laodicea for AD 60; destruction at Hierapolis rests on archaeology and later tradition.",["ploutonion","theatre"])
e("c. AD 50",50,"Birth of Epictetus","Stoic philosopher Epictetus born a slave at Hierapolis.",[W],"Birth year approximate.")
e("AD 80 (tradition)",80,"Martyrdom of Philip","Tradition places the martyrdom of the apostle Philip at Hierapolis in AD 80.",[U,W],"Tradition only; identity Apostle vs Evangelist debated since antiquity.",["martyrium_philip","tomb_philip"])
e("c. AD 84-86",85,"Frontinus Gate and Street","Proconsul Sextus Julius Frontinus builds the triple gate dedicated to Domitian and the colonnaded main street.",[W,TAN],"Dates 83/84/86 in different sources.",["frontinus_gate","plateia"])
e("Late 1st c. AD",95,"Latrine on Frontinus Street","Public latrine built just inside the Frontinus Gate.",[TAN],None,["latrine"])
e("AD 117-138 (often 'AD 129')",129,"Roman theatre completed","Theatre completed under Hadrian (inscription naming Tiberius Julius Myndius); often linked to a visit by Hadrian in 129.",[ATA,W],"Hadrianic visit/129 date not securely attested.",["theatre"])
e("2nd c. AD",150,"North Agora and Stoa-basilica","North Agora (280 x 170 m) built; Stoa-basilica on its E side late Hadrianic-early Antonine.",["https://www.thiasos.eu/wp-content/uploads/2020/05/14.Sacchi.pdf"],None,["north_agora"])
e("AD 193-211",205,"Severan theatre facade","Three-storey scaenae frons with relief friezes (Apollo/Artemis cycles, Dionysus, Severus' family) built under Septimius Severus.",[W,U,ATA],"Some museum captions date reliefs 'end of 2nd c.' or 'end of 3rd c.'.",["theatre","great_baths_museum"])
e("AD 215",215,"Caracalla and neokoros","Caracalla visits and grants the neokoros title.",[W,TAN],"Repeated by Wikipedia/TAN; primary attestation not checked.")
e("AD 222-235",228,"Nymphaeum of the Tritons","Monumental fountain on Frontinus Street dated by inscription to Severus Alexander.",[TAN],None,["nymphaeum_tritons"])
e("2nd half 3rd c. AD",270,"Sawmill relief","Sarcophagus of Marcus Aurelius Ammianos shows a water-powered stone sawmill - earliest known crank and connecting rod.",["https://en.wikipedia.org/wiki/Hierapolis_sawmill"],None,["north_necropolis"])
e("AD 352",352,"Theatre aquatic conversion","Major works on the scene building; orchestra made watertight (kolymbethra) for aquatic shows.",[W,ATA],None,["theatre"])
e("AD 370",370,"Last imperial visit","Emperor Valens visits during his Persian campaign - the last imperial visit.",[W,TAN])
e("4th c. AD",380,"Christianisation; Ploutonion closed","Ploutonion entrance filled/walled; earthquake damage to Agora; Ploutonion functional until 4th c.",[W,PLW,J32],None,["ploutonion"])
e("Late 4th c. AD",390,"Theodosian walls and gates","City wall circuit with North and South Byzantine gates, partly built from Agora stone.",[W,TAN],None,["city_walls","north_byzantine_gate","south_byzantine_gate"])
e("Early 5th c. AD",410,"Martyrium of St Philip","Octagonal martyrium built on the hill NE of the city; burned late 5th/early 6th c.",[W,U,TAN],None,["martyrium_philip"])
e("AD 531",531,"Metropolitan see","Justinian raises the bishop of Hierapolis to metropolitan.",[W])
e("6th c. AD",540,"Cathedral","Three-aisled cathedral with baptistery built.",[TAN],None,["cathedral"])
e("Early 7th c. AD",610,"Persian raids and great earthquake","Persian armies and a destructive earthquake devastate the city; theatre collapses; Antique Pool takes its present form.",[W,TAN],"Exact year not established in sources consulted.",["theatre","antique_pool"])
e("9th-11th c.",950,"Middle Byzantine village","Houses and olive-processing installations over the ruins (e.g., Ploutonion Phase V); 11th-c. courtyard house excavated.",[J32,W])
e("12th c.",1150,"Seljuk control","Area comes under the Seljuk sultanate of Konya.",[W,TAN])
e("1190",1190,"Third Crusade","Frederick Barbarossa's crusaders with Byzantine allies take the settlement.",[W,TAN])
e("13th c.",1250,"Seljuk castle","Turks build a fortress on the site (OSM 'Seldjuk Fortress Wall', near museum).",[W,TAN],None,[])
e("1354",1354,"Final earthquake","Great earthquake ends settlement within the ancient city.",[TAN,W],"Britannica gives 1334 for abandonment after an earthquake; Wikipedia's wording is garbled.",[])
e("1838",1838,"Laborde publishes views and plan","Léon de Laborde's Voyage de l'Asie Mineure publishes a plan of 'Pambouk Kalessi' and engravings of the petrified cascades and ruins.",["https://commons.wikimedia.org/wiki/File:Plan_de_Pambouk_Kalessi_(Hierapolis)_-_Laborde_L%C3%A9on_Emmanuel_Simon_Joseph_-_1838.jpg"],"Earlier travellers (e.g., 18th c.) also described the site; not catalogued here.")
e("24 Jun - 7 Jul 1887",1887,"Carl Humann's German survey","Carl Humann surveys and excavates for about two weeks; city plan dated 24 June-7 July 1887.",[HUM,W],None,[])
e("1898",1898,"'Altertümer von Hierapolis' published","Humann, Cichorius, Judeich and Winter publish the results (JdI Ergänzungsheft 4, Berlin, G. Reimer).",[ZEN,HUM],"Wikipedia/TAN wrongly give 1889 as publication year.")
e("1957",1957,"Italian Archaeological Mission (MAIER)","Systematic Italian excavations begin under Paolo Verzone; later directors include Francesco D'Andria and Grazia Semeraro.",[W,TAN])
e("1960s (1965)",1965,"First 'Plutonium' identification","Italian archaeologists identify a gas-emitting cave beside the Temple of Apollo as the Plutonium.",[PLW,W],"Later superseded by the 2013 identification of the sanctuary with dedicatory inscription.",["ploutonion","temple_apollo"])
e("1984",1984,"Museum opens in the Great Baths","Hierapolis Archaeology Museum installed in the Roman baths.",[W],None,["great_baths_museum"])
e("1988",1988,"UNESCO World Heritage","Hierapolis-Pamukkale inscribed, criteria (iii)(iv)(vii).",[U])
e("2004-2014",2010,"Theatre restoration","Major restoration of the theatre by the Italian mission.",[W,ATA],None,["theatre"])
e("26 July 2011",2011,"Tomb of St Philip announced","D'Andria announces a church built around a 1st-c. tomb identified as Philip's, ~40 m from the Martyrium.",[W,PHW,"https://www.johnsanidopoulos.com/2011/07/tomb-of-apostle-philip-discovered-in.html"],"Identification is the excavator's interpretation; tomb empty.",["tomb_philip"])
e("March 2013",2013,"Ploutonion rediscovered","D'Andria announces the Ploutonion sanctuary (excavated from 2008): dedication to Pluto and Kore, theatron, pool, cave; Cerberus and snake statues found later that year.",[J31,"https://archaeology.org/news/2013/04/02/130403-turkey-hierapolis-pluto-s-gate/","https://archaeology.org/news/2013/11/18/131118-turkey-hierapolis-plutonium-statues/"],None,["ploutonion"])
e("2018",2018,"CO2 study","Pfanz et al. publish measurements of lethal CO2 concentrations (up to 91%) at the Ploutonion.",["https://doi.org/10.1007/s12520-018-0599-5"],None,["ploutonion"])
E.sort(key=lambda x:x["sort_year"])
json.dump(E,open("timeline.json","w"),ensure_ascii=False,indent=1); print(len(E))
